import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { attendanceAPI, studentsAPI } from './api_service';

/** * ========================================================================
 * CONFIGURATION & THEME
 * ========================================================================
 */
const CONFIG = {
    DETECTION_DURATION: 10000,
    FRAME_INTERVAL: 600,
    MIN_CONFIDENCE: 0.4,
    VIDEO_WIDTH: 1280,
    VIDEO_HEIGHT: 720
};

const COLORS = {
    primary: '#4F46E5',
    primaryLight: '#EEF2FF',
    success: '#10B981',
    successLight: '#ECFDF5',
    danger: '#EF4444',
    dangerLight: '#FEF2F2',
    warning: '#F59E0B',
    warningLight: '#FFFBEB',
    textMain: '#1E293B',
    textMuted: '#64748B',
    border: '#E2E8F0',
    background: '#F8FAFC',
    surface: '#FFFFFF',
    overlay: 'rgba(0, 0, 0, 0.7)'
};

/** * ========================================================================
 * COMPOSANTS INTERNES (UI)
 * ========================================================================
 */

// Badge de statut stylisé
const StatusBadge = ({ active, detecting }) => (
    <div style={{
        ...styles.statusBadge,
        backgroundColor: detecting ? COLORS.warning : (active ? COLORS.success : COLORS.danger)
    }}>
        <span style={styles.pulseDot} />
        {detecting ? 'ANALYSE EN COURS...' : (active ? 'CAMÉRA PRÊTE' : 'HORS LIGNE')}
    </div>
);

// Ligne d'information pour le résultat
const InfoRow = ({ label, value, isBold }) => (
    <div style={styles.infoRow}>
        <span style={styles.infoLabel}>{label}</span>
        <span style={{ ...styles.infoValue, fontWeight: isBold ? '700' : '400', color: isBold ? COLORS.primary : COLORS.textMuted }}>
            {value}
        </span>
    </div>
);

/** * ========================================================================
 * COMPOSANT PRINCIPAL : CameraRecognition
 * ========================================================================
 */
const CameraRecognition = ({ addNotification }) => {
    // --- REFS ---
    const videoRef = useRef(null);
    const streamRef = useRef(null);
    const canvasRef = useRef(null);
    const detectionIntervalRef = useRef(null);
    const detectionTimeoutRef = useRef(null);
    const progressIntervalRef = useRef(null);

    // --- STATE : Caméra & Stream ---
    const [cameraActive, setCameraActive] = useState(false);
    const [videoReady, setVideoReady] = useState(false);
    const [cameraPermission, setCameraPermission] = useState('unknown');

    // --- STATE : Détection ---
    const [detecting, setDetecting] = useState(false);
    const [detectionProgress, setDetectionProgress] = useState(0);
    const [frameCount, setFrameCount] = useState(0);

    // --- STATE : Résultats ---
    const [matchResult, setMatchResult] = useState(null);
    const [capturedPhoto, setCapturedPhoto] = useState(null);
    const [enrollmentPhoto, setEnrollmentPhoto] = useState(null);
    const [error, setError] = useState(null);
    const [isLoading, setIsLoading] = useState(false);

    /**
     * INITIALISATION DU CANVAS
     */
    useEffect(() => {
        if (!canvasRef.current) {
            canvasRef.current = document.createElement('canvas');
        }
    }, []);

    /**
     * VÉRIFICATION DES PERMISSIONS (AUTO)
     */
    useEffect(() => {
        const checkPerms = async () => {
            try {
                if (navigator.permissions && navigator.permissions.query) {
                    const status = await navigator.permissions.query({ name: 'camera' });
                    setCameraPermission(status.state);
                    status.onchange = () => setCameraPermission(status.state);
                }
            } catch (e) {
                console.warn("Permission API non supportée");
            }
        };
        checkPerms();
    }, []);

    /**
     * LOGIQUE DE FERMETURE (STOP)
     */
    const stopCamera = useCallback(() => {
        console.log("Cleaning up camera resources...");

        if (detectionIntervalRef.current) clearInterval(detectionIntervalRef.current);
        if (detectionTimeoutRef.current) clearTimeout(detectionTimeoutRef.current);
        if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);

        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => {
                track.stop();
                console.log(`Track ${track.kind} stopped`);
            });
            streamRef.current = null;
        }

        if (videoRef.current) {
            videoRef.current.srcObject = null;
        }

        setCameraActive(false);
        setVideoReady(false);
        setDetecting(false);
        setDetectionProgress(0);
    }, []);

    /**
     * LOGIQUE D'ALLUMAGE (START)
     * Correction majeure : On utilise une approche forcée sur l'élément vidéo
     */
    const startCamera = async () => {
        console.log("Attempting to start camera...");
        setError(null);
        setIsLoading(true);

        try {
            // 1. Arrêter tout flux existant
            stopCamera();

            // 2. Demander les médias
            const constraints = {
                video: {
                    facingMode: 'user',
                    width: { ideal: CONFIG.VIDEO_WIDTH },
                    height: { ideal: CONFIG.VIDEO_HEIGHT }
                },
                audio: false
            };

            const stream = await navigator.mediaDevices.getUserMedia(constraints);
            console.log("Stream successfully acquired");

            streamRef.current = stream;

            // 3. Attacher au DOM
            if (videoRef.current) {
                videoRef.current.srcObject = stream;

                // Forcer le play
                videoRef.current.onloadedmetadata = () => {
                    videoRef.current.play()
                        .then(() => {
                            console.log("Video playback started");
                            setVideoReady(true);
                            setCameraActive(true);
                            setIsLoading(false);
                            addNotification?.('Caméra activée avec succès', 'success');
                        })
                        .catch(err => {
                            console.error("Play error:", err);
                            setError("Erreur lors de la lecture vidéo");
                        });
                };
            } else {
                throw new Error("Référence vidéo manquante");
            }

        } catch (err) {
            console.error("Camera Start Error:", err);
            let message = "Erreur d'accès à la caméra";
            if (err.name === 'NotAllowedError') message = "Permission refusée par l'utilisateur";
            if (err.name === 'NotFoundError') message = "Aucune caméra détectée";

            setError(message);
            setIsLoading(false);
            addNotification?.(message, 'error');
        }
    };

    /**
     * CAPTURE DE FRAME (CANVAS)
     */
    const getBase64Frame = useCallback((quality = 0.8) => {
        if (!videoRef.current || !videoReady) return null;

        const video = videoRef.current;
        const canvas = canvasRef.current;

        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;

        const ctx = canvas.getContext('2d');

        // Effet miroir pour l'utilisateur
        ctx.translate(canvas.width, 0);
        ctx.scale(-1, 1);
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

        return canvas.toDataURL('image/jpeg', quality);
    }, [videoReady]);

    /**
     * TRAITEMENT APRÈS SUCCÈS
     */
    const handleRecognitionSuccess = async (data, capturedImg) => {
        setCapturedPhoto(capturedImg);
        setMatchResult({
            name: data.student,
            email: data.email || 'Non renseigné',
            confidence: (data.confidence * 100).toFixed(1),
            attendanceId: data.attendance_id || 'TEMP-' + Math.random().toString(36).substr(2, 9),
            timestamp: new Date().toLocaleTimeString('fr-FR')
        });

        // Chercher la photo d'enrôlement
        try {
            if (data.student_id) {
                const res = await studentsAPI.getById(data.student_id);
                if (res?.data?.photo_url) setEnrollmentPhoto(res.data.photo_url);
            }
        } catch (e) {
            console.warn("Impossible de charger la photo de profil");
        }

        setDetecting(false);
        addNotification?.(`Entrée validée : ${data.student}`, 'success');
    };

    /**
     * MODE DÉTECTION CONTINUE (10s)
     */
    const runContinuousDetection = () => {
        if (!cameraActive || detecting) return;

        console.log("Starting 10s detection cycle...");
        setDetecting(true);
        setDetectionProgress(0);
        setFrameCount(0);
        setMatchResult(null);
        setError(null);

        let bestMatch = null;
        const startTime = Date.now();

        // Intervalle d'envoi API
        detectionIntervalRef.current = setInterval(async () => {
            const frame = getBase64Frame(0.7);
            if (!frame) return;

            setFrameCount(prev => prev + 1);

            try {
                const response = await attendanceAPI.recognize(frame);
                const result = response?.data;

                if (result?.success && result?.confidence > CONFIG.MIN_CONFIDENCE) {
                    if (!bestMatch || result.confidence > bestMatch.confidence) {
                        bestMatch = { ...result, frame };
                        console.log("New best match found:", result.student);
                    }
                }
            } catch (e) {
                console.error("API Call failed during scan");
            }
        }, CONFIG.FRAME_INTERVAL);

        // Intervalle UI (Barre de progression)
        progressIntervalRef.current = setInterval(() => {
            const elapsed = Date.now() - startTime;
            const progress = Math.min(100, (elapsed / CONFIG.DETECTION_DURATION) * 100);
            setDetectionProgress(progress);
        }, 50);

        // Timeout final
        detectionTimeoutRef.current = setTimeout(() => {
            clearInterval(detectionIntervalRef.current);
            clearInterval(progressIntervalRef.current);

            if (bestMatch) {
                handleRecognitionSuccess(bestMatch, bestMatch.frame);
            } else {
                setDetecting(false);
                setError("Échec : Aucun visage reconnu pendant la période de scan.");
                addNotification?.("Reconnaissance infructueuse", "warning");
            }
        }, CONFIG.DETECTION_DURATION);
    };

    /**
     * CAPTURE MANUELLE UNIQUE
     */
    const triggerSingleCapture = async () => {
        if (!videoReady || isLoading) return;

        setIsLoading(true);
        setError(null);
        const frame = getBase64Frame(0.9);

        try {
            const response = await attendanceAPI.recognize(frame);
            if (response?.data?.success) {
                handleRecognitionSuccess(response.data, frame);
            } else {
                setError(response?.data?.message || "Visage non identifié");
            }
        } catch (e) {
            setError("Erreur de communication avec le serveur");
        } finally {
            setIsLoading(false);
        }
    };

    /**
     * CLEANUP ON UNMOUNT
     */
    useEffect(() => {
        return () => stopCamera();
    }, [stopCamera]);

    // ========================================================================
    // RENDU COMPOSANT
    // ========================================================================

    return (
        <div style={styles.container}>
            {/* 1. SECTION HEADER */}
            <header style={styles.header}>
                <div style={styles.logoContainer}>
                    <div style={styles.logoCircle}>
                        <span style={{ fontSize: '1.5rem' }}>🔐</span>
                    </div>
                    <div>
                        <h1 style={styles.mainTitle}>Portail de Pointage Facial</h1>
                        <p style={styles.mainSubtitle}>Système de sécurité biométrique v4.0</p>
                    </div>
                </div>
                <div style={styles.headerStats}>
                    <div style={styles.statItem}>
                        <span style={styles.statLabel}>Permissions</span>
                        <span style={{...styles.statValue, color: cameraPermission === 'granted' ? COLORS.success : COLORS.danger}}>
                            {cameraPermission.toUpperCase()}
                        </span>
                    </div>
                </div>
            </header>

            {/* 2. ZONE VIDÉO PRINCIPALE */}
            <main style={styles.mainLayout}>
                <section style={styles.cameraSection}>
                    <div style={styles.videoWrapper}>
                        {cameraActive ? (
                            <video
                                ref={videoRef}
                                autoPlay
                                playsInline
                                muted
                                style={styles.videoElement}
                            />
                        ) : (
                            <div style={styles.cameraPlaceholder} onClick={startCamera}>
                                <div style={styles.iconCircle}>📹</div>
                                <p style={styles.placeholderText}>Caméra désactivée</p>
                                <button style={styles.btnPrimary}>Initialiser le flux</button>
                            </div>
                        )}

                        {/* Overlays */}
                        {cameraActive && <StatusBadge active={cameraActive} detecting={detecting} />}

                        {detecting && (
                            <div style={styles.scanLine} />
                        )}

                        {detecting && (
                            <div style={styles.frameInfo}>
                                Frames traitées: {frameCount}
                            </div>
                        )}
                    </div>

                    {/* Barre de progression */}
                    <div style={styles.progressContainer}>
                        <div style={{ ...styles.progressFill, width: `${detectionProgress}%` }} />
                    </div>

                    {/* Contrôles */}
                    <div style={styles.controlPanel}>
                        {!cameraActive ? (
                            <button onClick={startCamera} style={styles.btnLarge}>
                                🚀 ALLUMER LE SYSTÈME
                            </button>
                        ) : (
                            <div style={styles.btnGroup}>
                                <button 
                                    onClick={triggerSingleCapture} 
                                    disabled={detecting || isLoading}
                                    style={{...styles.btnBase, background: COLORS.primary}}
                                >
                                    {isLoading ? '⏳ ...' : '📸 CAPTURE RAPIDE'}
                                </button>
                                <button 
                                    onClick={runContinuousDetection} 
                                    disabled={detecting}
                                    style={{...styles.btnBase, background: COLORS.warning}}
                                >
                                    🔍 SCAN 10 SECONDES
                                </button>
                                <button 
                                    onClick={stopCamera} 
                                    style={{...styles.btnBase, background: COLORS.danger}}
                                >
                                    🛑 ARRÊTER
                                </button>
                            </div>
                        )}
                    </div>

                    {error && (
                        <div style={styles.errorMessage}>
                            <strong>⚠️ Erreur détectée :</strong> {error}
                        </div>
                    )}
                </section>

                {/* 3. SECTION RÉSULTATS (SIDEBAR) */}
                <aside style={styles.resultSidebar}>
                    {matchResult ? (
                        <div style={styles.resultCard}>
                            <h2 style={styles.cardTitle}>Résultat de l'Analyse</h2>

                            <div style={styles.resultImages}>
                                <div style={styles.imgBox}>
                                    <span style={styles.imgLabel}>Capture</span>
                                    <img src={capturedPhoto} style={styles.imgThumb} alt="Capture" />
                                </div>
                                <div style={styles.imgBox}>
                                    <span style={styles.imgLabel}>Profil</span>
                                    <div style={styles.imgPlaceholderBox}>
                                        {enrollmentPhoto ? (
                                            <img src={enrollmentPhoto} style={styles.imgThumb} alt="Profil" />
                                        ) : (
                                            <span style={{fontSize: '10px'}}>N/A</span>
                                        )}
                                    </div>
                                </div>
                            </div>

                            <div style={styles.infoList}>
                                <InfoRow label="Étudiant" value={matchResult.name} isBold />
                                <InfoRow label="Confiance" value={`${matchResult.confidence}%`} isBold />
                                <InfoRow label="E-mail" value={matchResult.email} />
                                <InfoRow label="ID Pointage" value={matchResult.attendanceId} />
                                <InfoRow label="Heure" value={matchResult.timestamp} />
                            </div>

                            <button onClick={() => setMatchResult(null)} style={styles.btnClear}>
                                EFFACER LE RÉSULTAT
                            </button>
                        </div>
                    ) : (
                        <div style={styles.emptySidebar}>
                            <p>En attente d'identification...</p>
                            <small>Utilisez l'un des modes de capture à gauche pour identifier un étudiant.</small>
                        </div>
                    )}
                </aside>
            </main>

            {/* 4. FOOTER DÉBUG */}
            <footer style={styles.debugFooter}>
                <span>Statut Vidéo: {videoReady ? 'READY' : 'WAITING'}</span>
                <span> | </span>
                <span>Résolution: {CONFIG.VIDEO_WIDTH}x{CONFIG.VIDEO_HEIGHT}</span>
            </footer>

            {/* STYLES INTERNES (INJECTION CSS) */}
            <style dangerouslySetInnerHTML={{ __html: animations }} />
        </div>
    );
};

